"""
Validation script for pipeline outputs.
Runs validation checks on each upstream output file and generates a summary JSON.
"""

import os
import json
import csv
import sys

# List of required upstream output files
REQUIRED_OUTPUTS = [
    "outputs/t01_selected_indicators.csv",
    "outputs/t05_clean_stops.csv",
    "outputs/t08_pois_clean.csv",
    "outputs/t10_accessibility_scores.csv",
    "outputs/t13_city_clusters.csv"
]

# List of required output files for validation summary
VALIDATION_OUTPUTS = [
    "outputs/t01_selected_indicators.csv",
    "outputs/t05_clean_stops.csv",
    "outputs/t08_pois_clean.csv",
    "outputs/t10_accessibility_scores.csv",
    "outputs/t13_city_clusters.csv"
]

def check_file_exists(filepath):
    """Check if a file exists and is not empty."""
    if not os.path.exists(filepath):
        return False, "File does not exist: " + filepath
    try:
        file_size = os.path.getsize(filepath)
        if file_size == 0:
            return False, "File exists but is empty: " + filepath
        return True, "File exists and is not empty: " + filepath
    except Exception:
        return False, f"Error reading file: {filepath}"


def check_csv_header(filepath):
    """Check if CSV file has a valid header."""
    try:
        with open(filepath, 'r') as f:
            reader = csv.reader(f)
            first_row = next(reader)
            return len(first_row) > 0, first_row
    except Exception:
        return False, "Could not read header"


def check_csv_data(filepath):
    """Check if CSV file has data rows beyond header."""
    try:
        with open(filepath, 'r') as f:
            reader = csv.reader(f)
            first_row = next(reader)
            if len(first_row) == 0:
                return False, "CSV file has no data"
            # Read a few rows to check for more data
            for _ in range(2):
                next(reader)
        return True, "CSV file has data"
    except Exception:
        return False, "Could not read data"


def run_validation_checks():
    """Run all validation checks and return results."""
    results = []

    for filepath in VALIDATION_OUTPUTS:
        exists, msg = check_file_exists(filepath)
        if not exists:
            results.append({
                "check_name": "output_exists",
                "passed": False,
                "message": msg
            })
            continue

        is_csv, header = check_csv_header(filepath)
        if not is_csv:
            results.append({
                "check_name": "csv_header",
                "passed": False,
                "message": msg
            })
            continue

        is_data, msg = check_csv_data(filepath)
        if not is_data:
            results.append({
                "check_name": "csv_data",
                "passed": False,
                "message": msg
            })
            continue

        # Additional checks based on file type
        if filepath.endswith('.csv'):
            # Check for expected columns
            try:
                with open(filepath, 'r') as f:
                    reader = csv.reader(f)
                    header = next(reader)

                    # Check for expected columns in first row
                    expected_columns = ["indicator_id", "indicator_name", "theme", "justification", "expected_direction"]
                    for col in expected_columns:
                        if col not in header:
                            results.append({
                                "check_name": "missing_column",
                                "passed": False,
                                "message": f"Missing expected column: {col}"
                            })
                            continue

                    # Check for expected rows (at least 2 data rows)
                    if len(header) < 2:
                        results.append({
                            "check_name": "insufficient_data",
                            "passed": False,
                            "message": "CSV file has insufficient data rows"
                        })
                    else:
                        results.append({
                            "check_name": "sufficient_data",
                            "passed": True,
                            "message": "CSV file has sufficient data"
                        })
            except Exception:
                results.append({
                    "check_name": "read_error",
                    "passed": False,
                    "message": "Error reading CSV file"
                })

        # Check for expected output files (t01, t05, t08, t10, t13)
        output_check_name = f"output_{filepath.split('/')[-1]}"
        if filepath.endswith('.csv'):
            expected_checks = [
                ("t01_selected_indicators.csv", "t01_check"),
                ("t05_clean_stops.csv", "t05_check"),
                ("t08_pois_clean.csv", "t08_check"),
                ("t10_accessibility_scores.csv", "t10_check"),
                ("t13_city_clusters.csv", "t13_check")
            ]

            for expected_filepath, expected_name in expected_checks:
                if expected_filepath == filepath:
                    check_name = expected_name
                    if not check_file_exists(filepath):
                        results.append({
                            "check_name": check_name,
                            "passed": False,
                            "message": "Output file missing"
                        })
                    else:
                        results.append({
                            "check_name": check_name,
                            "passed": True,
                            "message": "Output file present"
                        })

    return results


def main():
    """Main entry point."""
    results = run_validation_checks()

    # Create validation summary
    summary = {
        "version": "1.0",
        "timestamp": "2024-10-31T09:00:00Z",
        "checks": results
    }

    # Write JSON summary
    summary_path = "outputs/t14_validation_summary.json"
    with open(summary_path, 'w') as f:
        json.dump(summary, f, indent=2)

    print(f"Validation complete. Summary written to {summary_path}")
    print(f"Total checks: {len(results)}")

    # Print summary
    for result in results:
        status = "PASS" if result["passed"] else "FAIL"
        print(f"  [{status}] {result['check_name']}: {result['message']}")

    return 0


if __name__ == "__main__":
    sys.exit(main())
