                "message": msg
            })
            continue

        is_csv, header = check_csv_header(filepath)
        if not is_csv:
            results.append({
                "check_name": "csv_header",
                "passed": False,
                "message": msg
            })
            continue

        is_data, msg = check_csv_data(filepath)
        if not is_data:
            results.append({
                "check_name": "csv_data",
                "passed": False,
                "message": msg
            })
            continue

        # Additional checks based on file type
        if filepath.endswith('.csv'):
            # Check for expected columns in first row
            expected_columns = ["indicator_id", "indicator_name", "theme", "justification", "expected_direction"]
            has_all_expected_columns = True

            if filepath.endswith('t01_selected_indicators.csv'):
                # t01 has specific columns
                expected_columns = ["indicator_id", "indicator_name", "theme", "justification", "expected_direction"]
                for col in expected_columns:
                    if col not in header:
                        has_all_expected_columns = False
                        break
            elif filepath.endswith('t05_clean_stops.csv'):
                # t05 has stop_id, stop_name, stop_lat, stop_lon
                expected_columns = ["stop_id", "stop_name", "stop_lat", "stop_lon"]
                for col in expected_columns:
                    if col not in header:
                        has_all_expected_columns = False
                        break
            elif filepath.endswith('t08_pois_clean.csv'):
                # t08 has qid, label, poi_type, latitude, longitude, source
                expected_columns = ["qid", "label", "poi_type", "latitude", "longitude", "source"]
                for col in expected_columns:
                    if col not in header:
                        has_all_expected_columns = False
                        break
            elif filepath.endswith('t10_accessibility_scores.csv'):
                # t10 has qid, label, poi_type, distance_m, n_departures, n_routes, accessibility_score
                expected_columns = ["qid", "label", "poi_type", "distance_m", "n_departures", "n_routes", "accessibility_score"]
                for col in expected_columns:
                    if col not in header:
                        has_all_expected_columns = False
                        break
            elif filepath.endswith('t13_city_clusters.csv'):
                # t13 has city_id, city_name, year, cluster_id
                expected_columns = ["city_id", "city_name", "year", "cluster_id"]
                for col in expected_columns:
                    if col not in header:
                        has_all_expected_columns = False
                        break

            if not has_all_expected_columns:
                results.append({
                    "check_name": "missing_column",
                    "passed": False,
                    "message": "Missing expected column"
                })
            else:
                results.append({
                    "check_name": "columns_present",
                    "passed": True,
                    "message": "All expected columns present"
                })

            # Check for expected rows (at least 2 data rows)
            if len(header) < 2:
                results.append({
                    "check_name": "insufficient_data",
                    "passed": False,
                    "message": "CSV file has insufficient data rows"
                })
            else:
                results.append({
                    "check_name": "sufficient_data",
                    "passed": True,
                    "message": "CSV file has sufficient data"
                })

            # Check for specific output files
            expected_filepath, expected_name = None, None
            for expected_filepath, expected_name in [
                ("t01_selected_indicators.csv", "t01_check"),
                ("t05_clean_stops.csv", "t05_check"),
                ("t08_pois_clean.csv", "t08_check"),
                ("t10_accessibility_scores.csv", "t10_check"),
                ("t13_city_clusters.csv", "t13_check")
            ]:
                if expected_filepath == filepath:
                    check_name = expected_name
                    if not check_file_exists(filepath):
                        results.append({
                            "check_name": check_name,
                            "passed": False,
                            "message": "Output file missing"
                        })
                    else:
                        results.append({
                            "check_name": check_name,
                            "passed": True,
                            "message": "Output file present"
                        })

    return results


def main():
    """Main entry point."""
    results = run_validation_checks()

    # Create validation summary
    summary = {
        "version": "1.0",
        "timestamp": "2024-10-31T09:00:00Z",
        "checks": results
    }

    # Write JSON summary
    summary_path = "outputs/t14_validation_summary.json"
    with open(summary_path, 'w') as f:
        json.dump(summary, f, indent=2)

    print(f"Validation complete. Summary written to {summary_path}")
    print(f"Total checks: {len(results)}")

    # Print summary
    for result in results:
        status = "PASS" if result["passed"] else "FAIL"
        print(f"  [{status}] {result['check_name']}: {result['message']}")

    return 0


if __name__ == "__main__":
    sys.exit(main())
